class Solution {
public:
    int specialArray(vector<int>& nums) {
        int n = nums.size();
        vector<int> freq(n + 1, 0);
        for (int num : nums) {
            freq[min(num, n)]++;
        }
        int count = 0;
        for (int x = n; x >= 0; x--) {
            count += freq[x];
            if (count == x) return x;
        }
        return -1;
    }
};
